function getSpanishInsightPost(string $slug): ?array
{
    $posts = getSpanishInsightPosts();
    return $posts[$slug] ?? null;
}

function spanishInsightAnchor(string $heading): string
{
    $slug = strtolower(iconv("UTF-8", "ASCII//TRANSLIT", $heading) ?: $heading);
    $slug = preg_replace("/[^a-z0-9]+/", "-", $slug);
    return trim($slug, "-");
}

function formatSpanishInsightDate(string $date): string
{
    $timestamp = strtotime($date);
    if (!$timestamp) {
        return $date;
    }

    $months = [
        1 => "ene", 2 => "feb", 3 => "mar", 4 => "abr", 5 => "may", 6 => "jun",
        7 => "jul", 8 => "ago", 9 => "sep", 10 => "oct", 11 => "nov", 12 => "dic",
    ];

    return date("j", $timestamp) . " " . $months[(int) date("n", $timestamp)] . ", " . date("Y", $timestamp);
}
